INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_1_math_u3_L02_basic#1','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C1',1,'mc','auto','같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],true,'{"seq":1,"concept":"M5-1-u3-C1","difficulty":1,"kind":"mc","stem":"같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨1/3⟩ = ⟨2/6⟩","correct":true},{"t":"⟨1/3⟩ < ⟨2/6⟩","mis":"M5-1-u3-X04"},{"t":"⟨1/3⟩ > ⟨2/6⟩","mis":"M5-1-u3-X04"},{"t":"이름이 달라서 견줄 수 없다","mis":"M5-1-u3-X04"}],"explanation":["위 띠는 3칸 중 1칸, 아래 띠는 6칸 중 2칸을 색칠했어요.","색칠한 끝이 같은 자리에서 멈춰요 — 칸을 2배로 잘게 나누었을 뿐이에요.","그래서 ⟨1/3⟩ = ⟨2/6⟩ — 이름은 달라도 양은 같아요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"label":"⟨1/3⟩"},{"den":6,"num":2,"label":"⟨2/6⟩"}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨1/2⟩ = ⟨3/6⟩","correct":true},{"t":"⟨1/2⟩ < ⟨3/6⟩","mis":"M5-1-u3-X04"},{"t":"⟨1/2⟩ > ⟨3/6⟩","mis":"M5-1-u3-X04"},{"t":"이름이 달라서 견줄 수 없다","mis":"M5-1-u3-X04"}],"explanation":["위 띠는 2칸 중 1칸, 아래 띠는 6칸 중 3칸을 색칠했어요.","색칠한 끝이 같은 자리에서 멈춰요 — 칸을 3배로 잘게 나누었을 뿐이에요.","그래서 ⟨1/2⟩ = ⟨3/6⟩ — 이름은 달라도 양은 같아요."],"asset":{"type":"fbar","bars":[{"den":2,"num":1,"label":"⟨1/2⟩"},{"den":6,"num":3,"label":"⟨3/6⟩"}]}},{"stem":"이번에는 다른 보기예요. 같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨3/4⟩ = ⟨6/8⟩","correct":true},{"t":"⟨3/4⟩ < ⟨6/8⟩","mis":"M5-1-u3-X04"},{"t":"⟨3/4⟩ > ⟨6/8⟩","mis":"M5-1-u3-X04"},{"t":"이름이 달라서 견줄 수 없다","mis":"M5-1-u3-X04"}],"explanation":["위 띠는 4칸 중 3칸, 아래 띠는 8칸 중 6칸을 색칠했어요.","색칠한 끝이 같은 자리에서 멈춰요 — 칸을 2배로 잘게 나누었을 뿐이에요.","그래서 ⟨3/4⟩ = ⟨6/8⟩ — 이름은 달라도 양은 같아요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"label":"⟨3/4⟩"},{"den":8,"num":6,"label":"⟨6/8⟩"}]}}]}}'::jsonb),
('g5_1_math_u3_L02_basic#2','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C2',1,'sa','auto','⟨1/3⟩ = ⟨□/6⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u3-C2","difficulty":1,"kind":"sa","stem":"⟨1/3⟩ = ⟨□/6⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모 3에 2를 곱해 6이 되었어요 — 3 × 2 = 6.","분자에도 같은 수 2를 곱해요 — 1 × 2 = 2.","⟨1/3⟩ = ⟨2/6⟩예요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩ = ⟨□/12⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모 4에 3을 곱해 12가 되었어요 — 4 × 3 = 12.","분자에도 같은 수 3을 곱해요 — 1 × 3 = 3.","⟨1/4⟩ = ⟨3/12⟩이에요."]},{"stem":"⟨2/5⟩ = ⟨□/15⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["분모 5에 3을 곱해 15가 되었어요 — 5 × 3 = 15.","분자에도 같은 수 3을 곱해요 — 2 × 3 = 6.","⟨2/5⟩ = ⟨6/15⟩이에요."]}]}}'::jsonb),
('g5_1_math_u3_L02_basic#3','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C2',1,'mc','auto','⟨2/3⟩의 분모와 분자에 각각 3을 곱하면 어떤 분수가 되나요?',ARRAY['M5-1-u3-X01','M5-1-u3-X02']::text[],true,'{"seq":3,"concept":"M5-1-u3-C2","difficulty":1,"kind":"mc","stem":"⟨2/3⟩의 분모와 분자에 각각 3을 곱하면 어떤 분수가 되나요?","options":[{"t":"⟨6/9⟩","correct":true},{"t":"⟨5/6⟩","mis":"M5-1-u3-X01"},{"t":"⟨6/3⟩","mis":"M5-1-u3-X02"},{"t":"⟨2/9⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 3 × 3 = 9, 분자 2 × 3 = 6이에요.","⟨2/3⟩ = ⟨6/9⟩ — 분모와 분자에 같은 수를 곱해 크기는 그대로예요.","분모와 분자에 같은 수를 더하면 크기가 달라져요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩의 분모와 분자에 각각 3을 곱하면 어떤 분수가 되나요?","options":[{"t":"⟨3/12⟩","correct":true},{"t":"⟨4/7⟩","mis":"M5-1-u3-X01"},{"t":"⟨3/4⟩","mis":"M5-1-u3-X02"},{"t":"⟨1/12⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 4 × 3 = 12, 분자 1 × 3 = 3이에요.","⟨1/4⟩ = ⟨3/12⟩ — 분모와 분자에 같은 수를 곱해 크기는 그대로예요.","분모와 분자에 같은 수를 더하면 크기가 달라져요."]},{"stem":"⟨3/5⟩의 분모와 분자에 각각 2를 곱하면 어떤 분수가 되나요?","options":[{"t":"⟨6/10⟩","correct":true},{"t":"⟨5/7⟩","mis":"M5-1-u3-X01"},{"t":"⟨6/5⟩","mis":"M5-1-u3-X02"},{"t":"⟨3/10⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 5 × 2 = 10, 분자 3 × 2 = 6이에요.","⟨3/5⟩ = ⟨6/10⟩ — 분모와 분자에 같은 수를 곱해 크기는 그대로예요.","분모와 분자에 같은 수를 더하면 크기가 달라져요."]}]}}'::jsonb),
('g5_1_math_u3_L02_basic#4','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C2',1,'mc','auto','⟨8/12⟩의 분모와 분자를 각각 4로 나누면 어떤 분수가 되나요?',ARRAY['M5-1-u3-X01','M5-1-u3-X02']::text[],true,'{"seq":4,"concept":"M5-1-u3-C2","difficulty":1,"kind":"mc","stem":"⟨8/12⟩의 분모와 분자를 각각 4로 나누면 어떤 분수가 되나요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨4/8⟩","mis":"M5-1-u3-X01"},{"t":"⟨2/12⟩","mis":"M5-1-u3-X02"},{"t":"⟨8/3⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 12 ÷ 4 = 3, 분자 8 ÷ 4 = 2예요.","⟨8/12⟩ = ⟨2/3⟩ — 분모와 분자를 같은 수로 나누어도 크기는 그대로예요.","분모나 분자 한쪽만 나누면 크기가 달라져요."],"variant_rule":{"alt":[{"stem":"⟨6/9⟩의 분모와 분자를 각각 3으로 나누면 어떤 분수가 되나요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨3/6⟩","mis":"M5-1-u3-X01"},{"t":"⟨2/9⟩","mis":"M5-1-u3-X02"},{"t":"⟨6/3⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 9 ÷ 3 = 3, 분자 6 ÷ 3 = 2예요.","⟨6/9⟩ = ⟨2/3⟩ — 분모와 분자를 같은 수로 나누어도 크기는 그대로예요.","분모나 분자 한쪽만 나누면 크기가 달라져요."]},{"stem":"⟨10/15⟩의 분모와 분자를 각각 5로 나누면 어떤 분수가 되나요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨5/10⟩","mis":"M5-1-u3-X01"},{"t":"⟨2/15⟩","mis":"M5-1-u3-X02"},{"t":"⟨10/3⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 15 ÷ 5 = 3, 분자 10 ÷ 5 = 2예요.","⟨10/15⟩ = ⟨2/3⟩ — 분모와 분자를 같은 수로 나누어도 크기는 그대로예요.","분모나 분자 한쪽만 나누면 크기가 달라져요."]}]}}'::jsonb),
('g5_1_math_u3_L02_basic#5','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C2',2,'ox','auto','⟨2/3⟩의 분모와 분자에 각각 3을 더한 ⟨5/6⟩는 ⟨2/3⟩와 크기가 같아요.',ARRAY['M5-1-u3-X01']::text[],true,'{"seq":5,"concept":"M5-1-u3-C2","difficulty":2,"kind":"ox","stem":"⟨2/3⟩의 분모와 분자에 각각 3을 더한 ⟨5/6⟩는 ⟨2/3⟩와 크기가 같아요.","answer":"X","reason_options":[{"t":"⟨2/3⟩ = ⟨4/6⟩라 ⟨5/6⟩과는 색칠한 칸 수가 달라지므로","correct":true},{"t":"분모와 분자에 똑같이 3을 더했으니 크기가 같으므로","mis":"M5-1-u3-X01"}],"mis":"M5-1-u3-X01","explanation":["⟨2/3⟩를 6칸으로 나누면 ⟨4/6⟩ — 색칠한 칸이 4칸이에요.","⟨5/6⟩는 5칸을 색칠해 양이 더 많아요.","크기가 같은 분수는 곱하기·나누기로만 만들어요. 더하기로는 안 돼요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩의 분모와 분자에 각각 2를 곱한 ⟨6/8⟩은 ⟨3/4⟩과 크기가 같아요.","answer":"O","reason_options":[{"t":"분모와 분자에 0이 아닌 같은 수를 곱했으므로","correct":true},{"t":"분모와 분자가 커졌으니 더 큰 분수이므로","mis":"M5-1-u3-X04"}],"explanation":["분모 4 × 2 = 8, 분자 3 × 2 = 6이에요.","칸을 2배로 잘게 나누면 색칠한 칸도 2배가 돼요.","⟨3/4⟩ = ⟨6/8⟩ — 크기는 그대로예요."]}]}}'::jsonb),
('g5_1_math_u3_L02_basic#6','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C2',2,'mc','auto','크기가 같은 분수를 만들 때 분모와 분자에 곱할 수 없는 수는 어느 것인가요?',ARRAY['M5-1-u3-X03']::text[],true,'{"seq":6,"concept":"M5-1-u3-C2","difficulty":2,"kind":"mc","stem":"크기가 같은 분수를 만들 때 분모와 분자에 곱할 수 없는 수는 어느 것인가요?","options":[{"t":"0","correct":true},{"t":"1","mis":"M5-1-u3-X03"},{"t":"5","mis":"M5-1-u3-X03"},{"t":"10","mis":"M5-1-u3-X03"}],"explanation":["0을 곱하면 분모도 분자도 0이 되어 분수가 되지 않아요.","1을 곱하면 처음 분수 그대로이고, 5나 10을 곱하면 크기가 같은 분수가 돼요.","그래서 「0이 아닌 같은 수」라는 말이 꼭 붙어요."],"variant_rule":{"alt":[{"stem":"크기가 같은 분수를 만드는 방법으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"분모와 분자에 각각 0을 곱한다","correct":true},{"t":"분모와 분자에 같은 수를 곱한다","mis":"M5-1-u3-X14"},{"t":"분모와 분자를 같은 수로 나눈다","mis":"M5-1-u3-X14"},{"t":"분모와 분자를 공약수로 나눈다","mis":"M5-1-u3-X14"}],"explanation":["0을 곱하면 분모가 0이 되어 분수가 되지 않아요.","0이 아닌 같은 수를 곱하거나 같은 수로 나누면 크기가 같은 분수가 돼요.","그래서 옳지 않은 것은 「0을 곱한다」예요."]}]}}'::jsonb),
('g5_1_math_u3_L02_basic#7','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C2',2,'sa','auto','⟨3/7⟩과 크기가 같고 분모가 49인 분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u3-C2","difficulty":2,"kind":"sa","stem":"⟨3/7⟩과 크기가 같고 분모가 49인 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["분모 7을 49로 만들려면 7을 곱해요 — 7 × 7 = 49.","분자에도 7을 곱해요 — 3 × 7 = 21.","⟨3/7⟩ = ⟨21/49⟩ — 분자는 21이에요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩과 크기가 같고 분모가 12인 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["분모 4를 12로 만들려면 3을 곱해요 — 4 × 3 = 12.","분자에도 3을 곱해요 — 3 × 3 = 9.","⟨3/4⟩ = ⟨9/12⟩ — 분자는 9예요."]},{"stem":"⟨5/6⟩와 크기가 같고 분모가 36인 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["분모 6을 36으로 만들려면 6을 곱해요 — 6 × 6 = 36.","분자에도 6을 곱해요 — 5 × 6 = 30.","⟨5/6⟩ = ⟨30/36⟩ — 분자는 30이에요."]}]}}'::jsonb),
('g5_1_math_u3_L02_basic#8','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C1',2,'mc','auto','⟨4/6⟩와 크기가 같은 분수가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],true,'{"seq":8,"concept":"M5-1-u3-C1","difficulty":2,"kind":"mc","stem":"⟨4/6⟩와 크기가 같은 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨2/3⟩","mis":"M5-1-u3-X04"},{"t":"⟨8/12⟩","mis":"M5-1-u3-X04"},{"t":"⟨12/18⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨4/6⟩ = ⟨2/3⟩ = ⟨8/12⟩ = ⟨12/18⟩예요 — 모두 분모와 분자에 같은 수를 곱하거나 나눈 분수예요.","⟨3/5⟩은 ⟨4/6⟩의 분모와 분자에 같은 수를 곱하거나 나누어 만들 수 없어요.","⟨3/5⟩ ≠ ⟨4/6⟩ — 크기가 같은 분수가 아닌 것은 ⟨3/5⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩과 크기가 같은 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨6/8⟩","mis":"M5-1-u3-X04"},{"t":"⟨9/12⟩","mis":"M5-1-u3-X04"},{"t":"⟨15/20⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨3/4⟩ = ⟨6/8⟩ = ⟨9/12⟩ = ⟨15/20⟩예요 — 모두 분모와 분자에 같은 수를 곱하거나 나눈 분수예요.","⟨4/5⟩는 ⟨3/4⟩의 분모와 분자에 같은 수를 곱하거나 나누어 만들 수 없어요.","⟨4/5⟩ ≠ ⟨3/4⟩ — 크기가 같은 분수가 아닌 것은 ⟨4/5⟩예요."]},{"stem":"⟨2/5⟩와 크기가 같은 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨3/6⟩","correct":true},{"t":"⟨4/10⟩","mis":"M5-1-u3-X04"},{"t":"⟨6/15⟩","mis":"M5-1-u3-X04"},{"t":"⟨8/20⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨2/5⟩ = ⟨4/10⟩ = ⟨6/15⟩ = ⟨8/20⟩이에요 — 모두 분모와 분자에 같은 수를 곱하거나 나눈 분수예요.","⟨3/6⟩은 ⟨2/5⟩의 분모와 분자에 같은 수를 곱하거나 나누어 만들 수 없어요.","⟨3/6⟩ ≠ ⟨2/5⟩ — 크기가 같은 분수가 아닌 것은 ⟨3/6⟩이에요."]}]}}'::jsonb),
('g5_1_math_u3_L02_basic#9','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C2',2,'mc','auto','어떤 분수의 분모와 분자에 각각 5를 곱했더니 ⟨15/20⟩가 되었어요. 처음 분수는 어느 것인가요?',ARRAY['M5-1-u3-X14','M5-1-u3-X01','M5-1-u3-X02']::text[],true,'{"seq":9,"concept":"M5-1-u3-C2","difficulty":2,"kind":"mc","stem":"어떤 분수의 분모와 분자에 각각 5를 곱했더니 ⟨15/20⟩가 되었어요. 처음 분수는 어느 것인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨75/100⟩","mis":"M5-1-u3-X14"},{"t":"⟨10/15⟩","mis":"M5-1-u3-X01"},{"t":"⟨3/20⟩","mis":"M5-1-u3-X02"}],"explanation":["곱한 것을 되돌리려면 같은 수로 나누어요.","분모 20 ÷ 5 = 4, 분자 15 ÷ 5 = 3이에요.","처음 분수는 ⟨3/4⟩이고 ⟨3/4⟩ = ⟨15/20⟩예요."],"variant_rule":{"alt":[{"stem":"어떤 분수의 분모와 분자에 각각 4를 곱했더니 ⟨8/12⟩이 되었어요. 처음 분수는 어느 것인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨32/48⟩","mis":"M5-1-u3-X14"},{"t":"⟨4/8⟩","mis":"M5-1-u3-X01"},{"t":"⟨2/12⟩","mis":"M5-1-u3-X02"}],"explanation":["곱한 것을 되돌리려면 같은 수로 나누어요.","분모 12 ÷ 4 = 3, 분자 8 ÷ 4 = 2예요.","처음 분수는 ⟨2/3⟩이고 ⟨2/3⟩ = ⟨8/12⟩이에요."]},{"stem":"어떤 분수의 분모와 분자에 각각 3을 곱했더니 ⟨12/15⟩가 되었어요. 처음 분수는 어느 것인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨36/45⟩","mis":"M5-1-u3-X14"},{"t":"⟨9/12⟩","mis":"M5-1-u3-X01"},{"t":"⟨4/15⟩","mis":"M5-1-u3-X02"}],"explanation":["곱한 것을 되돌리려면 같은 수로 나누어요.","분모 15 ÷ 3 = 5, 분자 12 ÷ 3 = 4예요.","처음 분수는 ⟨4/5⟩이고 ⟨4/5⟩ = ⟨12/15⟩예요."]}]}}'::jsonb),
('g5_1_math_u3_L02_basic#10','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C1',3,'mc','auto','수직선에서 ⟨1/3⟩과 같은 자리를 가리키는 분수를 차례로 쓴 것은 어느 것인가요?',ARRAY['M5-1-u3-X01','M5-1-u3-X02','M5-1-u3-X13']::text[],true,'{"seq":10,"concept":"M5-1-u3-C1","difficulty":3,"kind":"mc","stem":"수직선에서 ⟨1/3⟩과 같은 자리를 가리키는 분수를 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨2/6⟩, ⟨3/9⟩, ⟨4/12⟩","correct":true},{"t":"⟨2/4⟩, ⟨3/5⟩, ⟨4/6⟩","mis":"M5-1-u3-X01"},{"t":"⟨1/6⟩, ⟨1/9⟩, ⟨1/12⟩","mis":"M5-1-u3-X02"},{"t":"⟨2/6⟩, ⟨3/9⟩, ⟨4/9⟩","mis":"M5-1-u3-X13"}],"explanation":["분모와 분자에 2, 3, 4를 차례로 곱해요.","⟨1/3⟩ = ⟨2/6⟩ = ⟨3/9⟩ = ⟨4/12⟩예요.","모두 수직선의 같은 자리를 가리켜요."],"variant_rule":{"alt":[{"stem":"수직선에서 ⟨1/4⟩과 같은 자리를 가리키는 분수를 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨2/8⟩, ⟨3/12⟩, ⟨4/16⟩","correct":true},{"t":"⟨2/5⟩, ⟨3/6⟩, ⟨4/7⟩","mis":"M5-1-u3-X01"},{"t":"⟨1/8⟩, ⟨1/12⟩, ⟨1/16⟩","mis":"M5-1-u3-X02"},{"t":"⟨2/8⟩, ⟨3/12⟩, ⟨4/12⟩","mis":"M5-1-u3-X13"}],"explanation":["분모와 분자에 2, 3, 4를 차례로 곱해요.","⟨1/4⟩ = ⟨2/8⟩ = ⟨3/12⟩ = ⟨4/16⟩예요.","모두 수직선의 같은 자리를 가리켜요."]},{"stem":"수직선에서 ⟨2/5⟩와 같은 자리를 가리키는 분수를 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨4/10⟩, ⟨6/15⟩, ⟨8/20⟩","correct":true},{"t":"⟨3/6⟩, ⟨4/7⟩, ⟨5/8⟩","mis":"M5-1-u3-X01"},{"t":"⟨2/10⟩, ⟨2/15⟩, ⟨2/20⟩","mis":"M5-1-u3-X02"},{"t":"⟨4/10⟩, ⟨6/15⟩, ⟨8/15⟩","mis":"M5-1-u3-X13"}],"explanation":["분모와 분자에 2, 3, 4를 차례로 곱해요.","⟨2/5⟩ = ⟨4/10⟩ = ⟨6/15⟩ = ⟨8/20⟩이에요.","모두 수직선의 같은 자리를 가리켜요."]}]}}'::jsonb),
('g5_1_math_u3_L02_challenge#1','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',2,'error','auto','⟨2/3⟩와 크기가 같은 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u3-X01','M5-1-u3-X14']::text[],true,'{"seq":1,"concept":"M5-1-u3-C2","difficulty":2,"kind":"error","stem":"⟨2/3⟩와 크기가 같은 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「분모와 분자에 3을 더하면 ⟨5/6⟩야.」","correct":true,"mis_target":"M5-1-u3-X01"},{"t":"도현 — 「분모와 분자에 2를 곱하면 ⟨4/6⟩야.」","mis":"M5-1-u3-X14"},{"t":"하은 — 「⟨8/12⟩의 분모와 분자를 4로 나누면 ⟨2/3⟩가 돼.」","mis":"M5-1-u3-X14"}],"explanation":["⟨2/3⟩ = ⟨4/6⟩이고, ⟨8/12⟩을 4로 나누면 ⟨2/3⟩예요 — 둘은 맞아요.","⟨5/6⟩는 ⟨2/3⟩와 크기가 달라요.","서윤은 더하기로 만들어 잘못 말했어요. 크기가 같은 분수는 곱하기·나누기로만 만들어요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩과 크기가 같은 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「분모와 분자에 2를 더하면 ⟨5/6⟩야.」","correct":true,"mis_target":"M5-1-u3-X01"},{"t":"라온 — 「분모와 분자에 2를 곱하면 ⟨6/8⟩이야.」","mis":"M5-1-u3-X14"},{"t":"예준 — 「⟨12/16⟩의 분모와 분자를 4로 나누면 ⟨3/4⟩이 돼.」","mis":"M5-1-u3-X14"}],"explanation":["⟨3/4⟩ = ⟨6/8⟩이고, ⟨12/16⟩를 4로 나누면 ⟨3/4⟩이에요 — 둘은 맞아요.","⟨5/6⟩는 ⟨3/4⟩과 크기가 달라요.","지민은 더하기로 만들어 잘못 말했어요. 크기가 같은 분수는 곱하기·나누기로만 만들어요."]}]}}'::jsonb),
('g5_1_math_u3_L02_challenge#2','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',2,'sa','auto','⟨9/15⟩와 크기가 같은 분수 중 분모가 가장 작은 분수의 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u3-C2","difficulty":2,"kind":"sa","stem":"⟨9/15⟩와 크기가 같은 분수 중 분모가 가장 작은 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모를 작게 하려면 분모와 분자를 같은 수로 나누어요.","9와 15의 최대공약수 3으로 나누면 9 ÷ 3 = 3, 15 ÷ 3 = 5예요.","⟨9/15⟩ = ⟨3/5⟩ — 더 나눌 수 없으니 분모는 5예요."],"variant_rule":{"alt":[{"stem":"⟨12/16⟩와 크기가 같은 분수 중 분모가 가장 작은 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모를 작게 하려면 분모와 분자를 같은 수로 나누어요.","12와 16의 최대공약수 4로 나누면 12 ÷ 4 = 3, 16 ÷ 4 = 4예요.","⟨12/16⟩ = ⟨3/4⟩ — 더 나눌 수 없으니 분모는 4예요."]},{"stem":"⟨14/35⟩와 크기가 같은 분수 중 분모가 가장 작은 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모를 작게 하려면 분모와 분자를 같은 수로 나누어요.","14와 35의 최대공약수 7로 나누면 14 ÷ 7 = 2, 35 ÷ 7 = 5예요.","⟨14/35⟩ = ⟨2/5⟩ — 더 나눌 수 없으니 분모는 5예요."]}]}}'::jsonb),
('g5_1_math_u3_L02_challenge#3','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',3,'sa','auto','⟨2/5⟩와 크기가 같은 분수 중 분모가 10보다 크고 30보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u3-C2","difficulty":3,"kind":"sa","stem":"⟨2/5⟩와 크기가 같은 분수 중 분모가 10보다 크고 30보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["⟨2/5⟩와 크기가 같은 분수의 분모는 5의 배수예요.","10보다 크고 30보다 작은 5의 배수는 15, 20, 25예요.","⟨6/15⟩, ⟨8/20⟩, ⟨10/25⟩ — 모두 3개예요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩과 크기가 같은 분수 중 분모가 10보다 크고 30보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["⟨3/4⟩과 크기가 같은 분수의 분모는 4의 배수예요.","10보다 크고 30보다 작은 4의 배수는 12, 16, 20, 24, 28이에요.","⟨9/12⟩, ⟨12/16⟩, ⟨15/20⟩, ⟨18/24⟩, ⟨21/28⟩ — 모두 5개예요."]},{"stem":"⟨1/6⟩과 크기가 같은 분수 중 분모가 10보다 크고 40보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["⟨1/6⟩과 크기가 같은 분수의 분모는 6의 배수예요.","10보다 크고 40보다 작은 6의 배수는 12, 18, 24, 30, 36이에요.","⟨2/12⟩, ⟨3/18⟩, ⟨4/24⟩, ⟨5/30⟩, ⟨6/36⟩ — 모두 5개예요."]}]}}'::jsonb),
('g5_1_math_u3_L02_challenge#4','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',3,'sa','auto','⟨3/8⟩과 크기가 같은 분수 중 분모와 분자의 합이 44인 분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u3-C2","difficulty":3,"kind":"sa","stem":"⟨3/8⟩과 크기가 같은 분수 중 분모와 분자의 합이 44인 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["⟨3/8⟩의 분모와 분자의 합은 3 + 8 = 11이에요.","분모와 분자에 같은 수를 곱하면 합도 그만큼 커져요 — 44 ÷ 11 = 4배.","분자는 3 × 4 = 12 — ⟨12/32⟩예요."],"variant_rule":{"alt":[{"stem":"⟨2/5⟩와 크기가 같은 분수 중 분모와 분자의 합이 35인 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["⟨2/5⟩의 분모와 분자의 합은 2 + 5 = 7이에요.","분모와 분자에 같은 수를 곱하면 합도 그만큼 커져요 — 35 ÷ 7 = 5배.","분자는 2 × 5 = 10 — ⟨10/25⟩이에요."]},{"stem":"⟨4/7⟩와 크기가 같은 분수 중 분모와 분자의 합이 55인 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["⟨4/7⟩의 분모와 분자의 합은 4 + 7 = 11이에요.","분모와 분자에 같은 수를 곱하면 합도 그만큼 커져요 — 55 ÷ 11 = 5배.","분자는 4 × 5 = 20 — ⟨20/35⟩이에요."]}]}}'::jsonb),
('g5_1_math_u3_L02_challenge#5','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',3,'mc','auto','⟨12/18⟩의 분모와 분자를 같은 수로 나누어 만들 수 있는 분수가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],true,'{"seq":5,"concept":"M5-1-u3-C2","difficulty":3,"kind":"mc","stem":"⟨12/18⟩의 분모와 분자를 같은 수로 나누어 만들 수 있는 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨6/9⟩","mis":"M5-1-u3-X04"},{"t":"⟨4/6⟩","mis":"M5-1-u3-X04"},{"t":"⟨2/3⟩","mis":"M5-1-u3-X04"}],"explanation":["12와 18을 함께 나누는 수는 공약수 2, 3, 6이에요.","⟨6/9⟩, ⟨4/6⟩, ⟨2/3⟩ — 모두 ⟨12/18⟩와 크기가 같아요.","⟨3/4⟩은 ⟨12/18⟩와 크기가 달라 만들 수 없어요."],"variant_rule":{"alt":[{"stem":"⟨16/24⟩의 분모와 분자를 같은 수로 나누어 만들 수 있는 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨4/8⟩","correct":true},{"t":"⟨8/12⟩","mis":"M5-1-u3-X04"},{"t":"⟨4/6⟩","mis":"M5-1-u3-X04"},{"t":"⟨2/3⟩","mis":"M5-1-u3-X04"}],"explanation":["16과 24를 함께 나누는 수는 공약수 2, 4, 8이에요.","⟨8/12⟩, ⟨4/6⟩, ⟨2/3⟩ — 모두 ⟨16/24⟩과 크기가 같아요.","⟨4/8⟩는 ⟨16/24⟩과 크기가 달라 만들 수 없어요."]},{"stem":"⟨20/30⟩의 분모와 분자를 같은 수로 나누어 만들 수 있는 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨5/6⟩","correct":true},{"t":"⟨10/15⟩","mis":"M5-1-u3-X04"},{"t":"⟨4/6⟩","mis":"M5-1-u3-X04"},{"t":"⟨2/3⟩","mis":"M5-1-u3-X04"}],"explanation":["20과 30을 함께 나누는 수는 공약수 2, 5, 10이에요.","⟨10/15⟩, ⟨4/6⟩, ⟨2/3⟩ — 모두 ⟨20/30⟩과 크기가 같아요.","⟨5/6⟩는 ⟨20/30⟩과 크기가 달라 만들 수 없어요."]}]}}'::jsonb),
('g5_1_math_u3_L02_challenge#6','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C1',3,'ox','auto','⟨1/3⟩의 한 칸을 2등분 하면 ⟨2/6⟩가 돼요. 칸이 잘아졌으니 색칠한 양은 줄었어요.',ARRAY['M5-1-u3-X04']::text[],true,'{"seq":6,"concept":"M5-1-u3-C1","difficulty":3,"kind":"ox","stem":"⟨1/3⟩의 한 칸을 2등분 하면 ⟨2/6⟩가 돼요. 칸이 잘아졌으니 색칠한 양은 줄었어요.","answer":"X","reason_options":[{"t":"조각이 2배 작아진 만큼 조각 개수가 2배 많아져 양은 그대로이므로","correct":true},{"t":"분모가 커지면 분수는 작아지므로","mis":"M5-1-u3-X04"}],"mis":"M5-1-u3-X04","explanation":["한 칸을 2등분 하면 칸은 6개, 색칠한 칸은 2개가 돼요.","작아진 만큼 많아지니 전체 양은 그대로예요.","⟨1/3⟩ = ⟨2/6⟩ — 이름만 바뀌었어요."],"variant_rule":{"alt":[{"stem":"⟨4/8⟩의 칸을 2개씩 묶으면 ⟨2/4⟩가 되고, 색칠한 양은 변하지 않아요.","answer":"O","reason_options":[{"t":"조각이 2배 커진 만큼 조각 개수가 절반이 되어 양은 그대로이므로","correct":true},{"t":"분모와 분자가 작아지면 분수도 작아지므로","mis":"M5-1-u3-X04"}],"explanation":["8칸을 2개씩 묶으면 4칸, 색칠한 4칸은 2칸이 돼요.","분모와 분자를 똑같이 2로 나눈 셈이에요.","⟨4/8⟩ = ⟨2/4⟩ — 양은 그대로예요."]}]}}'::jsonb),
('g5_1_math_u3_L02_challenge#7','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',3,'match','auto','크기가 같은 분수끼리 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u3-C2","difficulty":3,"kind":"match","stem":"크기가 같은 분수끼리 이으세요.","pairs":[{"l":"⟨1/2⟩","r":"⟨5/10⟩"},{"l":"⟨2/3⟩","r":"⟨8/12⟩"},{"l":"⟨3/4⟩","r":"⟨9/12⟩"}],"mis":"M5-1-u3-X13","explanation":["⟨1/2⟩의 분모와 분자에 5를 곱하면 ⟨5/10⟩예요.","⟨2/3⟩ = ⟨8/12⟩, ⟨3/4⟩ = ⟨9/12⟩예요 — 둘 다 분모가 12라 헷갈리기 쉬워요.","분모에 곱한 수만큼 분자에도 곱했는지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 크기가 같은 분수끼리 이으세요.","pairs":[{"l":"⟨1/3⟩","r":"⟨4/12⟩"},{"l":"⟨2/5⟩","r":"⟨6/15⟩"},{"l":"⟨3/5⟩","r":"⟨9/15⟩"}],"explanation":["⟨1/3⟩ = ⟨4/12⟩ — 분모와 분자에 4를 곱했어요.","⟨2/5⟩ = ⟨6/15⟩, ⟨3/5⟩ = ⟨9/15⟩ — 분모와 분자에 3을 곱했어요.","분모가 15로 같아도 분자가 다르면 다른 분수예요."]}]}}'::jsonb),
('g5_1_math_u3_L02_challenge#8','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',4,'sa','auto','⟨□/24⟩ = ⟨3/8⟩ = ⟨15/○⟩에서 □와 ○에 알맞은 수의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u3-C2","difficulty":4,"kind":"sa","stem":"⟨□/24⟩ = ⟨3/8⟩ = ⟨15/○⟩에서 □와 ○에 알맞은 수의 합은 얼마인가요? 숫자로 쓰세요.","answer":["49"],"explanation":["분모 24는 8 × 3 — □ = 3 × 3 = 9예요.","분자 15는 3 × 5 — ○ = 8 × 5 = 40이에요.","□ + ○ = 9 + 40 = 49예요."],"variant_rule":{"alt":[{"stem":"⟨□/20⟩ = ⟨2/5⟩ = ⟨14/○⟩에서 □와 ○에 알맞은 수의 합은 얼마인가요? 숫자로 쓰세요.","answer":["43"],"explanation":["분모 20은 5 × 4 — □ = 2 × 4 = 8이에요.","분자 14는 2 × 7 — ○ = 5 × 7 = 35예요.","□ + ○ = 8 + 35 = 43이에요."]},{"stem":"⟨□/18⟩ = ⟨5/6⟩ = ⟨20/○⟩에서 □와 ○에 알맞은 수의 합은 얼마인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["분모 18은 6 × 3 — □ = 5 × 3 = 15예요.","분자 20은 5 × 4 — ○ = 6 × 4 = 24예요.","□ + ○ = 15 + 24 = 39예요."]}]}}'::jsonb),
('g5_1_math_u3_L02_challenge#9','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C1',4,'essay','teacher','⟨2/3⟩의 분모와 분자에 각각 3을 더한 ⟨5/6⟩가 ⟨2/3⟩와 크기가 같지 않은 까닭을 띠 그림으로 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u3-C1","difficulty":4,"kind":"essay","stem":"⟨2/3⟩의 분모와 분자에 각각 3을 더한 ⟨5/6⟩가 ⟨2/3⟩와 크기가 같지 않은 까닭을 띠 그림으로 설명하세요.","answer_guide":{"answer":"예: ⟨2/3⟩를 6칸으로 나누면 ⟨4/6⟩로 6칸 중 4칸을 색칠한 것과 같다. ⟨5/6⟩는 6칸 중 5칸이라 색칠한 양이 더 많다. 그래서 두 분수는 크기가 다르고, 크기가 같은 분수는 더하기가 아니라 곱하기·나누기로 만들어야 한다.","scoring_points":["⟨2/3⟩ = ⟨4/6⟩임을 띠로 나타냈는가","⟨5/6⟩는 색칠한 칸이 하나 더 많음을 썼는가","더하기로는 크기가 같은 분수를 만들 수 없다고 맺었는가"]},"explanation":["⟨2/3⟩ = ⟨4/6⟩예요.","⟨5/6⟩는 6칸 중 5칸 — 4칸보다 많아요.","잘게 나누는 일은 곱셈이지 덧셈이 아니에요."]}'::jsonb),
('g5_1_math_u3_L02_challenge#10','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',4,'essay','teacher','크기가 같은 분수를 만들 때 「0이 아닌 같은 수」를 곱하거나 나누어야 하는 까닭을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u3-C2","difficulty":4,"kind":"essay","stem":"크기가 같은 분수를 만들 때 「0이 아닌 같은 수」를 곱하거나 나누어야 하는 까닭을 설명하세요.","answer_guide":{"answer":"예: 분모와 분자에 0을 곱하면 분모가 0이 되어 분수가 되지 않고, 0으로 나누는 것은 할 수 없다. 분모와 분자 중 한쪽에만 곱하거나 나누면 조각의 크기와 개수가 맞물려 바뀌지 않아 양이 달라진다. 그래서 0이 아닌 같은 수를 분모와 분자에 함께 써야 한다.","scoring_points":["0을 곱하거나 0으로 나눌 수 없는 까닭을 썼는가","분모와 분자에 「같은 수」를 써야 하는 까닭을 썼는가","조각의 크기와 개수가 함께 바뀌어 양이 지켜진다고 썼는가"]},"explanation":["0을 곱하면 분모가 0 — 분수가 되지 않아요.","한쪽에만 곱하면 조각 크기와 개수가 따로 바뀌어요.","0이 아닌 같은 수를 함께 써야 양이 지켜져요."]}'::jsonb),
('g5_1_math_u3_L03_basic#1','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',1,'mc','auto','⟨18/24⟩을 약분할 때 분모와 분자를 나눌 수 있는 수가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u3-X06']::text[],true,'{"seq":1,"concept":"M5-1-u3-C3","difficulty":1,"kind":"mc","stem":"⟨18/24⟩을 약분할 때 분모와 분자를 나눌 수 있는 수가 아닌 것은 어느 것인가요?","options":[{"t":"4","correct":true},{"t":"2","mis":"M5-1-u3-X06"},{"t":"3","mis":"M5-1-u3-X06"},{"t":"6","mis":"M5-1-u3-X06"}],"explanation":["18과 24의 공약수는 1, 2, 3, 6이에요.","약분은 1이 아닌 공약수 2, 3, 6으로 나누는 거예요.","4는 24의 약수이지만 18의 약수는 아니에요 — 그래서 4로는 약분할 수 없어요."],"variant_rule":{"alt":[{"stem":"⟨12/30⟩를 약분할 때 분모와 분자를 나눌 수 있는 수가 아닌 것은 어느 것인가요?","options":[{"t":"5","correct":true},{"t":"2","mis":"M5-1-u3-X06"},{"t":"3","mis":"M5-1-u3-X06"},{"t":"6","mis":"M5-1-u3-X06"}],"explanation":["12와 30의 공약수는 1, 2, 3, 6이에요.","약분은 1이 아닌 공약수 2, 3, 6으로 나누는 거예요.","5는 30의 약수이지만 12의 약수는 아니에요 — 그래서 5로는 약분할 수 없어요."]},{"stem":"⟨20/30⟩을 약분할 때 분모와 분자를 나눌 수 있는 수가 아닌 것은 어느 것인가요?","options":[{"t":"3","correct":true},{"t":"2","mis":"M5-1-u3-X06"},{"t":"5","mis":"M5-1-u3-X06"},{"t":"10","mis":"M5-1-u3-X06"}],"explanation":["20과 30의 공약수는 1, 2, 5, 10이에요.","약분은 1이 아닌 공약수 2, 5, 10으로 나누는 거예요.","3은 30의 약수이지만 20의 약수는 아니에요 — 그래서 3로는 약분할 수 없어요."]}]}}'::jsonb),
('g5_1_math_u3_L03_basic#2','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',1,'sa','auto','⟨12/16⟩를 4로 약분하면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u3-C3","difficulty":1,"kind":"sa","stem":"⟨12/16⟩를 4로 약분하면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모와 분자를 같은 수 4로 나누어요.","분자 12 ÷ 4 = 3, 분모 16 ÷ 4 = 4예요.","⟨12/16⟩ = ⟨3/4⟩ — 분자는 3이에요."],"variant_rule":{"alt":[{"stem":"⟨14/21⟩를 7로 약분하면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모와 분자를 같은 수 7로 나누어요.","분자 14 ÷ 7 = 2, 분모 21 ÷ 7 = 3이에요.","⟨14/21⟩ = ⟨2/3⟩ — 분자는 2예요."]},{"stem":"⟨24/30⟩를 6으로 약분하면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모와 분자를 같은 수 6으로 나누어요.","분자 24 ÷ 6 = 4, 분모 30 ÷ 6 = 5예요.","⟨24/30⟩ = ⟨4/5⟩ — 분자는 4예요."]}]}}'::jsonb),
('g5_1_math_u3_L03_basic#3','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',1,'mc','auto','⟨24/36⟩를 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u3-X05']::text[],true,'{"seq":3,"concept":"M5-1-u3-C3","difficulty":1,"kind":"mc","stem":"⟨24/36⟩를 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨12/18⟩","mis":"M5-1-u3-X05"},{"t":"⟨8/12⟩","mis":"M5-1-u3-X05"},{"t":"⟨6/9⟩","mis":"M5-1-u3-X05"}],"explanation":["24와 36의 공약수는 1, 2, 3, 4, 6, 12, 최대공약수는 12예요.","최대공약수로 나누면 한 번에 끝나요 — 24 ÷ 12 = 2, 36 ÷ 12 = 3.","⟨24/36⟩ = ⟨2/3⟩ — 공약수가 1뿐이라 기약분수예요."],"variant_rule":{"alt":[{"stem":"⟨30/45⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨10/15⟩","mis":"M5-1-u3-X05"},{"t":"⟨6/9⟩","mis":"M5-1-u3-X05"},{"t":"⟨2/45⟩","mis":"M5-1-u3-X02"}],"explanation":["30과 45의 공약수는 1, 3, 5, 15, 최대공약수는 15예요.","최대공약수로 나누면 한 번에 끝나요 — 30 ÷ 15 = 2, 45 ÷ 15 = 3.","⟨30/45⟩ = ⟨2/3⟩ — 공약수가 1뿐이라 기약분수예요."]},{"stem":"⟨16/40⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨8/20⟩","mis":"M5-1-u3-X05"},{"t":"⟨4/10⟩","mis":"M5-1-u3-X05"},{"t":"⟨2/40⟩","mis":"M5-1-u3-X02"}],"explanation":["16과 40의 공약수는 1, 2, 4, 8, 최대공약수는 8이에요.","최대공약수로 나누면 한 번에 끝나요 — 16 ÷ 8 = 2, 40 ÷ 8 = 5.","⟨16/40⟩ = ⟨2/5⟩ — 공약수가 1뿐이라 기약분수예요."]}]}}'::jsonb),
('g5_1_math_u3_L03_basic#4','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',1,'mc','auto','기약분수인 것은 어느 것인가요?',ARRAY['M5-1-u3-X05']::text[],true,'{"seq":4,"concept":"M5-1-u3-C3","difficulty":1,"kind":"mc","stem":"기약분수인 것은 어느 것인가요?","options":[{"t":"⟨7/9⟩","correct":true},{"t":"⟨6/8⟩","mis":"M5-1-u3-X05"},{"t":"⟨9/12⟩","mis":"M5-1-u3-X05"},{"t":"⟨10/15⟩","mis":"M5-1-u3-X05"}],"explanation":["⟨6/8⟩은 2로 약분돼요 · ⟨9/12⟩는 3으로 약분돼요 · ⟨10/15⟩은 5로 약분돼요.","7과 9의 공약수는 1뿐이에요.","그래서 더 약분할 수 없는 기약분수는 ⟨7/9⟩이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 기약분수인 것은 어느 것인가요?","options":[{"t":"⟨5/8⟩","correct":true},{"t":"⟨4/10⟩","mis":"M5-1-u3-X05"},{"t":"⟨6/9⟩","mis":"M5-1-u3-X05"},{"t":"⟨14/21⟩","mis":"M5-1-u3-X05"}],"explanation":["⟨4/10⟩는 2로 약분돼요 · ⟨6/9⟩은 3으로 약분돼요 · ⟨14/21⟩는 7로 약분돼요.","5와 8의 공약수는 1뿐이에요.","그래서 더 약분할 수 없는 기약분수는 ⟨5/8⟩예요."]},{"stem":"이번에는 다른 보기예요. 기약분수인 것은 어느 것인가요?","options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨9/15⟩","mis":"M5-1-u3-X05"},{"t":"⟨8/14⟩","mis":"M5-1-u3-X05"},{"t":"⟨12/20⟩","mis":"M5-1-u3-X05"}],"explanation":["⟨9/15⟩는 3으로 약분돼요 · ⟨8/14⟩은 2로 약분돼요 · ⟨12/20⟩는 4로 약분돼요.","8과 15의 공약수는 1뿐이에요.","그래서 더 약분할 수 없는 기약분수는 ⟨8/15⟩이에요."]}]}}'::jsonb),
('g5_1_math_u3_L03_basic#5','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',2,'sa','auto','⟨35/56⟩를 기약분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-1-u3-C3","difficulty":2,"kind":"sa","stem":"⟨35/56⟩를 기약분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["35와 56의 최대공약수는 7이에요.","35 ÷ 7 = 5, 56 ÷ 7 = 8이에요.","⟨35/56⟩ = ⟨5/8⟩ — 분자는 5예요."],"variant_rule":{"alt":[{"stem":"⟨28/42⟩을 기약분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["28과 42의 최대공약수는 14예요.","28 ÷ 14 = 2, 42 ÷ 14 = 3이에요.","⟨28/42⟩ = ⟨2/3⟩ — 분자는 2예요."]},{"stem":"⟨45/60⟩를 기약분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["45와 60의 최대공약수는 15예요.","45 ÷ 15 = 3, 60 ÷ 15 = 4예요.","⟨45/60⟩ = ⟨3/4⟩ — 분자는 3이에요."]}]}}'::jsonb),
('g5_1_math_u3_L03_basic#6','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',2,'error','auto','⟨9/12⟩를 약분한 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u3-X02','M5-1-u3-X14']::text[],true,'{"seq":6,"concept":"M5-1-u3-C3","difficulty":2,"kind":"error","stem":"⟨9/12⟩를 약분한 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「분자만 3으로 나누어 ⟨3/12⟩이야.」","correct":true,"mis_target":"M5-1-u3-X02"},{"t":"수아 — 「9 ÷ 3 = 3, 12 ÷ 3 = 4 — ⟨3/4⟩이야.」","mis":"M5-1-u3-X14"},{"t":"민재 — 「공약수 3으로 분모와 분자를 함께 나누었으니 약분이야.」","mis":"M5-1-u3-X14"}],"explanation":["약분은 분모와 분자를 같은 공약수로 함께 나누는 거예요.","⟨9/12⟩ = ⟨3/4⟩ — 바르게 약분했어요.","지호의 말처럼 분자만 나누면 조각 개수만 줄어 양이 작아져요."],"variant_rule":{"alt":[{"stem":"⟨10/15⟩을 약분한 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「분자만 5로 나누어 ⟨2/15⟩야.」","correct":true,"mis_target":"M5-1-u3-X02"},{"t":"세빈 — 「10 ÷ 5 = 2, 15 ÷ 5 = 3 — ⟨2/3⟩야.」","mis":"M5-1-u3-X14"},{"t":"도율 — 「공약수 5로 분모와 분자를 함께 나누었으니 약분이야.」","mis":"M5-1-u3-X14"}],"explanation":["약분은 분모와 분자를 같은 공약수로 함께 나누는 거예요.","⟨10/15⟩ = ⟨2/3⟩ — 바르게 약분했어요.","하랑의 말처럼 분자만 나누면 조각 개수만 줄어 양이 작아져요."]}]}}'::jsonb),
('g5_1_math_u3_L03_basic#7','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',2,'sa','auto','분모가 56인 분수를 약분했더니 ⟨4/7⟩가 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u3-C3","difficulty":2,"kind":"sa","stem":"분모가 56인 분수를 약분했더니 ⟨4/7⟩가 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["약분한 것을 되돌리면 분모와 분자에 같은 수를 곱해요.","분모 7을 56으로 만들려면 7 × 8 = 56 — 8을 곱해요.","분자도 4 × 8 = 32 — 처음 분수는 ⟨32/56⟩예요."],"variant_rule":{"alt":[{"stem":"분모가 42인 분수를 약분했더니 ⟨5/6⟩가 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["약분한 것을 되돌리면 분모와 분자에 같은 수를 곱해요.","분모 6을 42로 만들려면 6 × 7 = 42 — 7을 곱해요.","분자도 5 × 7 = 35 — 처음 분수는 ⟨35/42⟩예요."]},{"stem":"분모가 45인 분수를 약분했더니 ⟨2/9⟩가 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["약분한 것을 되돌리면 분모와 분자에 같은 수를 곱해요.","분모 9를 45로 만들려면 9 × 5 = 45 — 5를 곱해요.","분자도 2 × 5 = 10 — 처음 분수는 ⟨10/45⟩이에요."]}]}}'::jsonb),
('g5_1_math_u3_L03_basic#8','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',2,'mc','auto','하루 24시간 중 3시간을 분수로 나타내고 기약분수로 고치면 어느 것인가요?',ARRAY['M5-1-u3-X05','M5-1-u3-X02','M5-1-u3-X13']::text[],true,'{"seq":8,"concept":"M5-1-u3-C3","difficulty":2,"kind":"mc","stem":"하루 24시간 중 3시간을 분수로 나타내고 기약분수로 고치면 어느 것인가요?","options":[{"t":"⟨1/8⟩","correct":true},{"t":"⟨3/24⟩","mis":"M5-1-u3-X05"},{"t":"⟨1/24⟩","mis":"M5-1-u3-X02"},{"t":"⟨8/24⟩","mis":"M5-1-u3-X13"}],"explanation":["24시간 중 3시간은 ⟨3/24⟩이에요.","3과 24의 최대공약수 3으로 약분해요 — 3 ÷ 3 = 1, 24 ÷ 3 = 8.","⟨3/24⟩ = ⟨1/8⟩이에요."],"variant_rule":{"alt":[{"stem":"한 시간 60분 중 15분을 분수로 나타내고 기약분수로 고치면 어느 것인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨15/60⟩","mis":"M5-1-u3-X05"},{"t":"⟨1/60⟩","mis":"M5-1-u3-X02"},{"t":"⟨4/60⟩","mis":"M5-1-u3-X13"}],"explanation":["60분 중 15분은 ⟨15/60⟩예요.","15와 60의 최대공약수 15로 약분해요 — 15 ÷ 15 = 1, 60 ÷ 15 = 4.","⟨15/60⟩ = ⟨1/4⟩이에요."]},{"stem":"1년 12달 중 4달을 분수로 나타내고 기약분수로 고치면 어느 것인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨4/12⟩","mis":"M5-1-u3-X05"},{"t":"⟨1/12⟩","mis":"M5-1-u3-X02"},{"t":"⟨3/12⟩","mis":"M5-1-u3-X13"}],"explanation":["12달 중 4달은 ⟨4/12⟩예요.","4와 12의 최대공약수 4로 약분해요 — 4 ÷ 4 = 1, 12 ÷ 4 = 3.","⟨4/12⟩ = ⟨1/3⟩이에요."]}]}}'::jsonb),
('g5_1_math_u3_L03_basic#9','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',2,'ox','auto','⟨18/24⟩을 2로 약분한 ⟨9/12⟩는 기약분수예요.',ARRAY['M5-1-u3-X05']::text[],true,'{"seq":9,"concept":"M5-1-u3-C3","difficulty":2,"kind":"ox","stem":"⟨18/24⟩을 2로 약분한 ⟨9/12⟩는 기약분수예요.","answer":"X","reason_options":[{"t":"9와 12의 공약수에 3이 남아 있어 더 약분할 수 있으므로","correct":true},{"t":"한 번 약분했으니 기약분수이므로","mis":"M5-1-u3-X05"}],"mis":"M5-1-u3-X05","explanation":["9와 12의 공약수는 1, 3이에요.","3으로 한 번 더 약분하면 ⟨9/12⟩ = ⟨3/4⟩이에요.","공약수가 1뿐이어야 기약분수 — ⟨3/4⟩이 기약분수예요."],"variant_rule":{"alt":[{"stem":"⟨12/18⟩를 최대공약수 6으로 약분하면 한 번에 기약분수 ⟨2/3⟩가 돼요.","answer":"O","reason_options":[{"t":"최대공약수로 나누면 남는 공약수가 1뿐이므로","correct":true},{"t":"최대공약수로 나누면 분수의 크기가 작아지므로","mis":"M5-1-u3-X04"}],"explanation":["12와 18의 최대공약수는 6이에요.","12 ÷ 6 = 2, 18 ÷ 6 = 3 — ⟨12/18⟩ = ⟨2/3⟩.","2와 3의 공약수는 1뿐이라 기약분수예요."]}]}}'::jsonb),
('g5_1_math_u3_L03_basic#10','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',3,'mc','auto','약분하여 ⟨2/3⟩가 되는 분수가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],true,'{"seq":10,"concept":"M5-1-u3-C3","difficulty":3,"kind":"mc","stem":"약분하여 ⟨2/3⟩가 되는 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨12/16⟩","correct":true},{"t":"⟨10/15⟩","mis":"M5-1-u3-X04"},{"t":"⟨14/21⟩","mis":"M5-1-u3-X04"},{"t":"⟨18/27⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨10/15⟩ = ⟨2/3⟩ · ⟨14/21⟩ = ⟨2/3⟩ · ⟨18/27⟩ = ⟨2/3⟩예요.","⟨12/16⟩를 기약분수로 나타내면 ⟨3/4⟩이에요.","그래서 ⟨2/3⟩가 되지 않는 것은 ⟨12/16⟩예요."],"variant_rule":{"alt":[{"stem":"약분하여 ⟨3/4⟩이 되는 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨15/25⟩","correct":true},{"t":"⟨9/12⟩","mis":"M5-1-u3-X04"},{"t":"⟨15/20⟩","mis":"M5-1-u3-X04"},{"t":"⟨21/28⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨9/12⟩ = ⟨3/4⟩ · ⟨15/20⟩ = ⟨3/4⟩ · ⟨21/28⟩ = ⟨3/4⟩이에요.","⟨15/25⟩를 기약분수로 나타내면 ⟨3/5⟩이에요.","그래서 ⟨3/4⟩이 되지 않는 것은 ⟨15/25⟩예요."]},{"stem":"약분하여 ⟨3/5⟩이 되는 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨12/18⟩","correct":true},{"t":"⟨9/15⟩","mis":"M5-1-u3-X04"},{"t":"⟨12/20⟩","mis":"M5-1-u3-X04"},{"t":"⟨18/30⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨9/15⟩ = ⟨3/5⟩ · ⟨12/20⟩ = ⟨3/5⟩ · ⟨18/30⟩ = ⟨3/5⟩이에요.","⟨12/18⟩를 기약분수로 나타내면 ⟨2/3⟩예요.","그래서 ⟨3/5⟩이 되지 않는 것은 ⟨12/18⟩예요."]}]}}'::jsonb),
