('g5_1_math_u3_L06_challenge#7','math',5,1,'u3','L06','g5_1_math_u3_L06_challenge','lesson_challenge','M5-1-u3-C6',3,'ox','auto','⟨1/2⟩, 0.5, ⟨50/100⟩은 모두 같은 수예요.',ARRAY['M5-1-u3-X12']::text[],true,'{"seq":7,"concept":"M5-1-u3-C6","difficulty":3,"kind":"ox","stem":"⟨1/2⟩, 0.5, ⟨50/100⟩은 모두 같은 수예요.","answer":"O","reason_options":[{"t":"⟨1/2⟩ = ⟨5/10⟩ = ⟨50/100⟩이고 ⟨5/10⟩ = 0.5이므로","correct":true},{"t":"세 수에 모두 숫자 5가 들어 있으므로","mis":"M5-1-u3-X12"}],"mis":"M5-1-u3-X12","explanation":["⟨1/2⟩의 분모와 분자에 5를 곱하면 ⟨5/10⟩, 50을 곱하면 ⟨50/100⟩이에요.","⟨5/10⟩ = 0.5예요.","그래서 ⟨1/2⟩ = 0.5 = ⟨50/100⟩ — 모두 같은 수예요."],"variant_rule":{"alt":[{"stem":"0.08은 ⟨8/10⟩과 같아요.","answer":"X","reason_options":[{"t":"0.08은 소수 두 자리 수라 ⟨8/100⟩이므로","correct":true},{"t":"소수점 아래 숫자가 8 하나뿐이므로","mis":"M5-1-u3-X12"}],"explanation":["0.08은 소수점 아래 둘째 자리에 8이 있어요.","소수 두 자리 수는 분모가 100 — 0.08 = ⟨8/100⟩이에요.","⟨8/10⟩ = 0.8이에요."]}]}}'::jsonb),
