('g5_1_math_u4_L02_basic#9','math',5,1,'u4','L02','g5_1_math_u4_L02_basic','lesson_basic','M5-1-u4-C1',2,'ox','auto','우쿨렐레 수와 줄 수의 표에서 아래 줄이 4씩 늘어나는 것만 보아도 우쿨렐레 100개의 줄 수를 곱셈 한 번으로 구할 수 있어요.',ARRAY['M5-1-u4-X01']::text[],true,'{"seq":9,"concept":"M5-1-u4-C1","difficulty":2,"kind":"ox","stem":"우쿨렐레 수와 줄 수의 표에서 아래 줄이 4씩 늘어나는 것만 보아도 우쿨렐레 100개의 줄 수를 곱셈 한 번으로 구할 수 있어요.","answer":"X","reason_options":[{"t":"한 줄 규칙으로는 4를 99번 더해야 하고, 위아래 짝(4배)을 보아야 100 × 4로 한 번에 구하므로","correct":true},{"t":"4씩 늘어나니 100 + 4로 바로 구할 수 있으므로","mis":"M5-1-u4-X01"}],"mis":"M5-1-u4-X01","explanation":["아래 줄만 보면 「4씩 늘어난다」까지예요 — 100번째까지 4를 99번 더해야 해요.","위아래 짝을 보면 줄 수는 우쿨렐레 수의 4배예요.","그래서 100 × 4 = 400 — 짝을 보아야 한 번에 닿아요."],"variant_rule":{"alt":[{"stem":"원호가 12살일 때 동생은 9살, 13살일 때 10살이에요. 동생 나이는 원호 나이에 따라 하나로 정해지니 두 나이는 대응 관계예요.","answer":"O","reason_options":[{"t":"원호 나이가 정해지면 동생 나이가 늘 3살 적은 수로 하나로 정해지므로","correct":true},{"t":"두 사람 모두 해마다 1살씩 늘어나므로","mis":"M5-1-u4-X01"}],"explanation":["원호 나이 □가 정해지면 동생 나이는 □보다 3 적은 수로 하나예요.","「해마다 1살씩」은 한 사람의 나이만 본 한 줄 이야기예요.","두 나이 사이의 짝(3살 차)을 보아야 대응 관계예요."]}]}}'::jsonb),
('g5_1_math_u4_L02_basic#10','math',5,1,'u4','L02','g5_1_math_u4_L02_basic','lesson_basic','M5-1-u4-C1',3,'sa','auto','우쿨렐레 수를 1, 2, 3, …으로 늘려 가며 줄 수를 4, 8, 12, …으로 적었어요. 4부터 4씩 더해 가며 우쿨렐레 25개의 줄 수까지 가려면 4를 몇 번 더해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-1-u4-C1","difficulty":3,"kind":"sa","stem":"우쿨렐레 수를 1, 2, 3, …으로 늘려 가며 줄 수를 4, 8, 12, …으로 적었어요. 4부터 4씩 더해 가며 우쿨렐레 25개의 줄 수까지 가려면 4를 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["24","24번"],"explanation":["우쿨렐레 1개일 때가 4이고, 하나 늘 때마다 4를 한 번 더해요.","25개까지 가려면 25 − 1 = 24번 더해요 — 4 + 4 × 24 = 100.","25 × 4 = 100처럼 짝의 규칙으로 곱하면 한 번에 닿아요."],"variant_rule":{"alt":[{"stem":"삼각형 수를 1, 2, 3, …으로 늘려 가며 변 수를 3, 6, 9, …으로 적었어요. 3부터 3씩 더해 가며 삼각형 30개의 변 수까지 가려면 3을 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["29","29번"],"explanation":["삼각형 1개일 때가 3이고, 하나 늘 때마다 3을 한 번 더해요.","30개까지 가려면 30 − 1 = 29번 더해요 — 3 + 3 × 29 = 90.","30 × 3 = 90처럼 짝의 규칙으로 곱하면 한 번에 닿아요."]},{"stem":"꿀벌 수를 1, 2, 3, …으로 늘려 가며 다리 수를 6, 12, 18, …으로 적었어요. 6부터 6씩 더해 가며 꿀벌 16마리의 다리 수까지 가려면 6을 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["15","15번"],"explanation":["꿀벌 1마리일 때가 6이고, 하나 늘 때마다 6을 한 번 더해요.","16마리까지 가려면 16 − 1 = 15번 더해요 — 6 + 6 × 15 = 96.","16 × 6 = 96처럼 짝의 규칙으로 곱하면 한 번에 닿아요."]}]}}'::jsonb),
('g5_1_math_u4_L02_challenge#1','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C2',2,'error','auto','우쿨렐레 수와 줄 수의 대응표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u4-X03','M5-1-u4-X13']::text[],true,'{"seq":1,"concept":"M5-1-u4-C2","difficulty":2,"kind":"error","stem":"우쿨렐레 수와 줄 수의 대응표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「첫 짝이 1과 4니 줄 수는 우쿨렐레 수보다 3 많아.」","correct":true,"mis_target":"M5-1-u4-X03"},{"t":"도현 — 「위아래로 짝지어 보면 줄 수는 우쿨렐레 수의 4배야.」","mis":"M5-1-u4-X13"},{"t":"하은 — 「우쿨렐레 수가 3일 때 줄 수는 12야.」","mis":"M5-1-u4-X13"}],"explanation":["짝 1과 4, 2와 8, 3과 12를 모두 보면 줄 수는 우쿨렐레 수의 4배예요.","「3 많다」는 첫 짝에서만 맞아요 — 둘째 짝은 2와 8로 6 차이예요.","서윤은 짝 하나만 보고 관계를 정해 잘못 말했어요."],"asset":{"type":"numgrid","rows":[["우쿨렐레 수",1,2,3,4,5],["줄 수",4,8,12,16,20]],"name":"대응표"},"variant_rule":{"alt":[{"stem":"삼각형 수와 변의 수의 대응표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「첫 짝이 1과 3이니 변의 수는 삼각형 수보다 2 많아.」","correct":true,"mis_target":"M5-1-u4-X03"},{"t":"라온 — 「위아래로 짝지어 보면 변의 수는 삼각형 수의 3배야.」","mis":"M5-1-u4-X13"},{"t":"예준 — 「삼각형 수가 3일 때 변의 수는 9야.」","mis":"M5-1-u4-X13"}],"explanation":["짝 1과 3, 2와 6, 3과 9를 모두 보면 변의 수는 삼각형 수의 3배예요.","「2 많다」는 첫 짝에서만 맞아요 — 둘째 짝은 2와 6으로 4 차이예요.","지민은 짝 하나만 보고 관계를 정해 잘못 말했어요."],"asset":{"type":"numgrid","rows":[["삼각형 수",1,2,3,4,5],["변의 수",3,6,9,12,15]],"name":"대응표"}},{"stem":"피자 수와 조각 수의 대응표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤슬 — 「첫 짝이 1과 8이니 조각 수는 피자 수보다 7 많아.」","correct":true,"mis_target":"M5-1-u4-X03"},{"t":"가온 — 「위아래로 짝지어 보면 조각 수는 피자 수의 8배야.」","mis":"M5-1-u4-X13"},{"t":"다솜 — 「피자 수가 3일 때 조각 수는 24야.」","mis":"M5-1-u4-X13"}],"explanation":["짝 1과 8, 2와 16, 3과 24를 모두 보면 조각 수는 피자 수의 8배예요.","「7 많다」는 첫 짝에서만 맞아요 — 둘째 짝은 2와 16으로 14 차이예요.","윤슬은 짝 하나만 보고 관계를 정해 잘못 말했어요."],"asset":{"type":"numgrid","rows":[["피자 수",1,2,3,4],["조각 수",8,16,24,32]],"name":"대응표"}}]}}'::jsonb),
('g5_1_math_u4_L02_challenge#2','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C3',2,'mc','auto','두 양이 대응 관계인 것은 어느 것인가요?',ARRAY['M5-1-u4-X05']::text[],true,'{"seq":2,"concept":"M5-1-u4-C3","difficulty":2,"kind":"mc","stem":"두 양이 대응 관계인 것은 어느 것인가요?","options":[{"t":"자전거 수와 바퀴 수","correct":true},{"t":"내 키와 좋아하는 색깔 수","mis":"M5-1-u4-X05"},{"t":"오늘 날씨와 내 나이","mis":"M5-1-u4-X05"},{"t":"내 몸무게와 가진 책 수","mis":"M5-1-u4-X05"}],"explanation":["내 키와 좋아하는 색깔 수 · 오늘 날씨와 내 나이 · 내 몸무게와 가진 책 수는 한 쪽이 정해져도 다른 쪽이 하나로 정해지지 않아요.","자전거 수와 바퀴 수는 한 쪽이 정해지면 다른 쪽도 하나로 정해져요.","그래서 대응 관계인 것은 「자전거 수와 바퀴 수」예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 두 양이 대응 관계인 것은 어느 것인가요?","options":[{"t":"주 수와 날 수","correct":true},{"t":"신발 크기와 좋아하는 과일 수","mis":"M5-1-u4-X05"},{"t":"내 키와 가진 연필 수","mis":"M5-1-u4-X05"},{"t":"오늘 기온과 반 친구 수","mis":"M5-1-u4-X05"}],"explanation":["신발 크기와 좋아하는 과일 수 · 내 키와 가진 연필 수 · 오늘 기온과 반 친구 수는 한 쪽이 정해져도 다른 쪽이 하나로 정해지지 않아요.","주 수와 날 수는 한 쪽이 정해지면 다른 쪽도 하나로 정해져요.","그래서 대응 관계인 것은 「주 수와 날 수」예요."]},{"stem":"이번에는 다른 보기예요. 두 양이 대응 관계인 것은 어느 것인가요?","options":[{"t":"피자 수와 조각 수","correct":true},{"t":"내 나이와 좋아하는 노래 수","mis":"M5-1-u4-X05"},{"t":"머리카락 길이와 가진 공책 수","mis":"M5-1-u4-X05"},{"t":"오늘 날씨와 짝꿍 이름","mis":"M5-1-u4-X05"}],"explanation":["내 나이와 좋아하는 노래 수 · 머리카락 길이와 가진 공책 수 · 오늘 날씨와 짝꿍 이름은 한 쪽이 정해져도 다른 쪽이 하나로 정해지지 않아요.","피자 수와 조각 수는 한 쪽이 정해지면 다른 쪽도 하나로 정해져요.","그래서 대응 관계인 것은 「피자 수와 조각 수」예요."]}]}}'::jsonb),
('g5_1_math_u4_L02_challenge#3','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C2',3,'sa','auto','꿀벌 수와 다리 수의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u4-C2","difficulty":3,"kind":"sa","stem":"꿀벌 수와 다리 수의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["다리 수는 꿀벌 수의 6배예요.","?는 위 칸이라 아래 수 30에서 거꾸로 가요 — 30 ÷ 6 = 5.","?에 알맞은 수는 5예요."],"asset":{"type":"numgrid","rows":[["꿀벌 수",1,2,3,4,null,6],["다리 수",6,12,18,24,30,36]],"name":"대응표","q":[0,5]},"variant_rule":{"alt":[{"stem":"피자 수와 조각 수의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["조각 수는 피자 수의 8배예요.","?는 위 칸이라 아래 수 48에서 거꾸로 가요 — 48 ÷ 8 = 6.","?에 알맞은 수는 6이에요."],"asset":{"type":"numgrid","rows":[["피자 수",1,2,3,4,5,null],["조각 수",8,16,24,32,40,48]],"name":"대응표","q":[0,6]}},{"stem":"원호 나이와 동생 나이의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["동생 나이는 원호 나이보다 3 적어요.","?는 위 칸이라 아래 수 13에서 거꾸로 가요 — 13 + 3 = 16.","?에 알맞은 수는 16이에요."],"asset":{"type":"numgrid","rows":[["원호 나이",12,13,14,15,null,17],["동생 나이",9,10,11,12,13,14]],"name":"대응표","q":[0,5]}}]}}'::jsonb),
('g5_1_math_u4_L02_challenge#4','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C1',3,'sa','auto','우쿨렐레 수를 1, 2, 3, …으로 늘려 가며 줄 수를 4, 8, 12, …으로 적었어요. 4부터 4씩 더해 가며 우쿨렐레 100개의 줄 수까지 가려면 4를 몇 번 더해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u4-C1","difficulty":3,"kind":"sa","stem":"우쿨렐레 수를 1, 2, 3, …으로 늘려 가며 줄 수를 4, 8, 12, …으로 적었어요. 4부터 4씩 더해 가며 우쿨렐레 100개의 줄 수까지 가려면 4를 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["99","99번"],"explanation":["우쿨렐레 1개일 때가 4이고, 하나 늘 때마다 4를 한 번 더해요.","100개까지 가려면 100 − 1 = 99번 더해요 — 4 + 4 × 99 = 400.","100 × 4 = 400처럼 짝의 규칙으로 곱하면 한 번에 닿아요."],"variant_rule":{"alt":[{"stem":"꿀벌 수를 1, 2, 3, …으로 늘려 가며 날개 수를 4, 8, 12, …으로 적었어요. 4부터 4씩 더해 가며 꿀벌 50마리의 날개 수까지 가려면 4를 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["49","49번"],"explanation":["꿀벌 1마리일 때가 4이고, 하나 늘 때마다 4를 한 번 더해요.","50마리까지 가려면 50 − 1 = 49번 더해요 — 4 + 4 × 49 = 200.","50 × 4 = 200처럼 짝의 규칙으로 곱하면 한 번에 닿아요."]},{"stem":"삼각형 수를 1, 2, 3, …으로 늘려 가며 변 수를 3, 6, 9, …으로 적었어요. 3부터 3씩 더해 가며 삼각형 80개의 변 수까지 가려면 3을 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["79","79번"],"explanation":["삼각형 1개일 때가 3이고, 하나 늘 때마다 3을 한 번 더해요.","80개까지 가려면 80 − 1 = 79번 더해요 — 3 + 3 × 79 = 240.","80 × 3 = 240처럼 짝의 규칙으로 곱하면 한 번에 닿아요."]}]}}'::jsonb),
('g5_1_math_u4_L02_challenge#5','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C2',3,'mc','auto','위아래 짝이 「△는 □의 3배」인 대응표를 짝으로 적은 것은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04','M5-1-u4-X03']::text[],true,'{"seq":5,"concept":"M5-1-u4-C2","difficulty":3,"kind":"mc","stem":"위아래 짝이 「△는 □의 3배」인 대응표를 짝으로 적은 것은 어느 것인가요?","options":[{"t":"1과 3, 2와 6, 3과 9","correct":true},{"t":"1과 4, 2와 5, 3과 6","mis":"M5-1-u4-X02"},{"t":"3과 1, 6과 2, 9와 3","mis":"M5-1-u4-X04"},{"t":"1과 3, 2와 5, 3과 7","mis":"M5-1-u4-X03"}],"explanation":["「△는 □의 3배」면 □에 3을 곱한 수가 △예요.","1 × 3 = 3, 2 × 3 = 6, 3 × 3 = 9예요.","그래서 짝은 1과 3, 2와 6, 3과 9예요."],"variant_rule":{"alt":[{"stem":"위아래 짝이 「△는 □의 4배」인 대응표를 짝으로 적은 것은 어느 것인가요?","options":[{"t":"1과 4, 2와 8, 3과 12","correct":true},{"t":"1과 5, 2와 6, 3과 7","mis":"M5-1-u4-X02"},{"t":"4와 1, 8과 2, 12와 3","mis":"M5-1-u4-X04"},{"t":"1과 4, 2와 6, 3과 8","mis":"M5-1-u4-X03"}],"explanation":["「△는 □의 4배」면 □에 4를 곱한 수가 △예요.","1 × 4 = 4, 2 × 4 = 8, 3 × 4 = 12예요.","그래서 짝은 1과 4, 2와 8, 3과 12예요."]},{"stem":"위아래 짝이 「△는 □의 5배」인 대응표를 짝으로 적은 것은 어느 것인가요?","options":[{"t":"1과 5, 2와 10, 3과 15","correct":true},{"t":"1과 6, 2와 7, 3과 8","mis":"M5-1-u4-X02"},{"t":"5와 1, 10과 2, 15와 3","mis":"M5-1-u4-X04"},{"t":"1과 5, 2와 7, 3과 9","mis":"M5-1-u4-X03"}],"explanation":["「△는 □의 5배」면 □에 5를 곱한 수가 △예요.","1 × 5 = 5, 2 × 5 = 10, 3 × 5 = 15예요.","그래서 짝은 1과 5, 2와 10, 3과 15예요."]}]}}'::jsonb),
('g5_1_math_u4_L02_challenge#6','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C3',3,'ox','auto','내 키가 정해지면 내가 좋아하는 색깔 수도 하나로 정해지므로 두 양은 대응 관계예요.',ARRAY['M5-1-u4-X05']::text[],true,'{"seq":6,"concept":"M5-1-u4-C3","difficulty":3,"kind":"ox","stem":"내 키가 정해지면 내가 좋아하는 색깔 수도 하나로 정해지므로 두 양은 대응 관계예요.","answer":"X","reason_options":[{"t":"키가 같은 친구들도 좋아하는 색깔 수는 저마다 달라 하나로 정해지지 않으므로","correct":true},{"t":"키와 색깔 수 모두 수로 나타낼 수 있으므로","mis":"M5-1-u4-X05"}],"mis":"M5-1-u4-X05","explanation":["키가 140 cm인 친구가 여럿이어도 좋아하는 색깔 수는 저마다 달라요.","한 쪽이 정해져도 다른 쪽이 하나로 정해지지 않아요.","그래서 키와 좋아하는 색깔 수는 대응 관계가 아니에요."],"variant_rule":{"alt":[{"stem":"피자 수가 정해지면 피자 조각 수도 하나로 정해지므로 두 양은 대응 관계예요(한 판은 8조각).","answer":"O","reason_options":[{"t":"한 판에 8조각으로 정해져 있어 판 수가 정해지면 조각 수가 딱 하나로 정해지므로","correct":true},{"t":"피자는 여러 사람이 나누어 먹으므로","mis":"M5-1-u4-X05"}],"explanation":["한 판은 8조각으로 정해져 있어요.","판 수가 정해지면 조각 수는 판 수의 8배로 하나예요.","그래서 피자 수와 조각 수는 대응 관계예요."]}]}}'::jsonb),
('g5_1_math_u4_L02_challenge#7','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C2',3,'sa','auto','꿀벌 한 마리는 날개가 4개, 다리가 6개예요. 날개가 모두 36개라면 다리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u4-C2","difficulty":3,"kind":"sa","stem":"꿀벌 한 마리는 날개가 4개, 다리가 6개예요. 날개가 모두 36개라면 다리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["54","54개"],"explanation":["날개 수는 꿀벌 수의 4배 — 꿀벌은 36 ÷ 4 = 9마리예요.","다리 수는 꿀벌 수의 6배예요.","9 × 6 = 54 — 다리는 54개예요."],"variant_rule":{"alt":[{"stem":"꿀벌 한 마리는 날개가 4개, 다리가 6개예요. 날개가 모두 44개라면 다리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["66","66개"],"explanation":["날개 수는 꿀벌 수의 4배 — 꿀벌은 44 ÷ 4 = 11마리예요.","다리 수는 꿀벌 수의 6배예요.","11 × 6 = 66 — 다리는 66개예요."]},{"stem":"꿀벌 한 마리는 날개가 4개, 다리가 6개예요. 날개가 모두 28개라면 다리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["42","42개"],"explanation":["날개 수는 꿀벌 수의 4배 — 꿀벌은 28 ÷ 4 = 7마리예요.","다리 수는 꿀벌 수의 6배예요.","7 × 6 = 42 — 다리는 42개예요."]}]}}'::jsonb),
('g5_1_math_u4_L02_challenge#8','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C2',4,'sa','auto','원호는 늘 동생보다 3살 많아요. 두 사람의 나이를 더했더니 31살이에요. 동생은 몇 살인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u4-C2","difficulty":4,"kind":"sa","stem":"원호는 늘 동생보다 3살 많아요. 두 사람의 나이를 더했더니 31살이에요. 동생은 몇 살인가요? 숫자로 쓰세요.","answer":["14","14살"],"explanation":["원호 나이는 동생 나이보다 3 많아요 — 합에서 3을 빼면 동생 나이의 2배예요.","31 − 3 = 28, 28 ÷ 2 = 14예요.","동생은 14살, 원호는 17살 — 14 + 17 = 31로 맞아요."],"variant_rule":{"alt":[{"stem":"언니는 늘 나보다 4살 많아요. 두 사람의 나이를 더했더니 30살이에요. 나는 몇 살인가요? 숫자로 쓰세요.","answer":["13","13살"],"explanation":["언니 나이는 나 나이보다 4 많아요 — 합에서 4를 빼면 나 나이의 2배예요.","30 − 4 = 26, 26 ÷ 2 = 13이에요.","나는 13살, 언니는 17살 — 13 + 17 = 30으로 맞아요."]},{"stem":"형은 늘 나보다 2살 많아요. 두 사람의 나이를 더했더니 26살이에요. 나는 몇 살인가요? 숫자로 쓰세요.","answer":["12","12살"],"explanation":["형 나이는 나 나이보다 2 많아요 — 합에서 2를 빼면 나 나이의 2배예요.","26 − 2 = 24, 24 ÷ 2 = 12예요.","나는 12살, 형은 14살 — 12 + 14 = 26으로 맞아요."]}]}}'::jsonb),
('g5_1_math_u4_L02_challenge#9','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C1',4,'essay','teacher','우쿨렐레 수와 줄 수의 표에서 「줄 수는 4씩 늘어난다」와 「줄 수는 우쿨렐레 수의 4배」는 어떻게 다른지, 우쿨렐레 100개의 줄 수를 구하는 방법과 함께 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u4-C1","difficulty":4,"kind":"essay","stem":"우쿨렐레 수와 줄 수의 표에서 「줄 수는 4씩 늘어난다」와 「줄 수는 우쿨렐레 수의 4배」는 어떻게 다른지, 우쿨렐레 100개의 줄 수를 구하는 방법과 함께 설명하세요.","answer_guide":{"answer":"예: 「4씩 늘어난다」는 아래 줄 한 줄만 본 것이고, 「4배」는 우쿨렐레 수와 줄 수를 위아래로 짝지어 본 대응 관계이다. 4씩 늘어난다는 것만 알면 100개까지 4를 99번 더해야 하지만, 4배라는 짝을 알면 100 × 4 = 400으로 한 번에 구할 수 있다.","scoring_points":["「4씩 늘어난다」는 한 줄, 「4배」는 두 양의 짝이라고 구별했는가","100 × 4 = 400으로 구했는가","짝을 알면 먼 자리 값을 한 번에 구한다고 맺었는가"]},"explanation":["한 줄만 보면 「4씩 늘어난다」예요.","두 양을 짝지으면 「4배」가 보여요.","100 × 4 = 400 — 짝의 규칙으로 한 번에 구해요."]}'::jsonb),
('g5_1_math_u4_L02_challenge#10','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C3',4,'essay','teacher','「오늘 날씨와 내 나이」가 대응 관계가 아닌 까닭을 대응 관계의 뜻을 써서 설명하고, 대응 관계인 두 양을 하나 예로 드세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u4-C3","difficulty":4,"kind":"essay","stem":"「오늘 날씨와 내 나이」가 대응 관계가 아닌 까닭을 대응 관계의 뜻을 써서 설명하고, 대응 관계인 두 양을 하나 예로 드세요.","answer_guide":{"answer":"예: 대응 관계는 한 양이 변할 때 다른 양이 그에 따라 하나로 정해지는 관계이다. 오늘 날씨가 맑든 비가 오든 내 나이는 날씨에 따라 정해지지 않으므로 대응 관계가 아니다. 자전거 수와 바퀴 수는 자전거 수가 정해지면 바퀴 수가 2배로 하나로 정해지므로 대응 관계이다.","scoring_points":["대응 관계의 뜻(하나로 정해짐)을 썼는가","날씨에 따라 나이가 정해지지 않는다고 썼는가","대응 관계인 두 양을 바르게 예로 들었는가"]},"explanation":["대응 관계는 한 양이 정해지면 다른 양이 하나로 정해지는 관계예요.","날씨가 정해져도 나이는 정해지지 않아요.","자전거 수와 바퀴 수처럼 하나로 정해지는 두 양이 대응 관계예요."]}'::jsonb),
('g5_1_math_u4_L03_basic#1','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C4',1,'mc','auto','우쿨렐레 한 개에 줄이 4개예요. 우쿨렐레 수를 □, 줄 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04']::text[],true,'{"seq":1,"concept":"M5-1-u4-C4","difficulty":1,"kind":"mc","stem":"우쿨렐레 한 개에 줄이 4개예요. 우쿨렐레 수를 □, 줄 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 4 = △","correct":true},{"t":"□ + 4 = △","mis":"M5-1-u4-X02"},{"t":"△ × 4 = □","mis":"M5-1-u4-X04"},{"t":"□ − 4 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(줄 수)는 □(우쿨렐레 수)의 4배예요.","그 말을 그대로 옮기면 □ × 4 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."],"variant_rule":{"alt":[{"stem":"자동차 한 대에 바퀴가 4개예요. 자동차 수를 □, 바퀴 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 4 = △","correct":true},{"t":"□ + 4 = △","mis":"M5-1-u4-X02"},{"t":"△ × 4 = □","mis":"M5-1-u4-X04"},{"t":"□ − 4 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(바퀴 수)는 □(자동차 수)의 4배예요.","그 말을 그대로 옮기면 □ × 4 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]},{"stem":"곤충 한 마리에 다리가 6개예요. 곤충 수를 □, 다리 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 6 = △","correct":true},{"t":"□ + 6 = △","mis":"M5-1-u4-X02"},{"t":"△ × 6 = □","mis":"M5-1-u4-X04"},{"t":"□ − 6 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(다리 수)는 □(곤충 수)의 6배예요.","그 말을 그대로 옮기면 □ × 6 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]}]}}'::jsonb),
('g5_1_math_u4_L03_basic#2','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C4',1,'sa','auto','□ × 5 = △에서 □가 9일 때 △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u4-C4","difficulty":1,"kind":"sa","stem":"□ × 5 = △에서 □가 9일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["□ 자리에 9를 넣어요.","9 × 5 = 45예요.","△는 45예요."],"variant_rule":{"alt":[{"stem":"□ × 6 = △에서 □가 8일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["□ 자리에 8을 넣어요.","8 × 6 = 48이에요.","△는 48이에요."]},{"stem":"□ × 4 = △에서 □가 12일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["□ 자리에 12를 넣어요.","12 × 4 = 48이에요.","△는 48이에요."]}]}}'::jsonb),
('g5_1_math_u4_L03_basic#3','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C4',1,'sa','auto','□ × 4 = △에서 △가 32일 때 □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u4-C4","difficulty":1,"kind":"sa","stem":"□ × 4 = △에서 △가 32일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["△ 자리에 32가 오도록 □를 찾아요 — 되돌리는 셈을 해요.","32 ÷ 4 = 8이에요.","□는 8이에요. 8 × 4 = 32로 확인해요."],"variant_rule":{"alt":[{"stem":"□ × 7 = △에서 △가 56일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["△ 자리에 56이 오도록 □를 찾아요 — 되돌리는 셈을 해요.","56 ÷ 7 = 8이에요.","□는 8이에요. 8 × 7 = 56으로 확인해요."]},{"stem":"□ × 3 = △에서 △가 27일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["△ 자리에 27이 오도록 □를 찾아요 — 되돌리는 셈을 해요.","27 ÷ 3 = 9예요.","□는 9예요. 9 × 3 = 27로 확인해요."]}]}}'::jsonb),
('g5_1_math_u4_L03_basic#4','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C5',1,'mc','auto','□ × 4 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X04','M5-1-u4-X08','M5-1-u4-X02']::text[],true,'{"seq":4,"concept":"M5-1-u4-C5","difficulty":1,"kind":"mc","stem":"□ × 4 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ ÷ 4 = □","correct":true},{"t":"△ × 4 = □","mis":"M5-1-u4-X04"},{"t":"□ ÷ 4 = △","mis":"M5-1-u4-X08"},{"t":"△ + 4 = □","mis":"M5-1-u4-X02"}],"explanation":["□ × 4 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ ÷ 4 = □ — 셈이 거꾸로 바뀌어요.","□ = 3이면 3 × 4 = 12, 거꾸로 12 ÷ 4 = 3으로 같은 짝이에요."],"variant_rule":{"alt":[{"stem":"□ × 6 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ ÷ 6 = □","correct":true},{"t":"△ × 6 = □","mis":"M5-1-u4-X04"},{"t":"□ ÷ 6 = △","mis":"M5-1-u4-X08"},{"t":"△ + 6 = □","mis":"M5-1-u4-X02"}],"explanation":["□ × 6 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ ÷ 6 = □ — 셈이 거꾸로 바뀌어요.","□ = 3이면 3 × 6 = 18, 거꾸로 18 ÷ 6 = 3으로 같은 짝이에요."]},{"stem":"□ × 9 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ ÷ 9 = □","correct":true},{"t":"△ × 9 = □","mis":"M5-1-u4-X04"},{"t":"□ ÷ 9 = △","mis":"M5-1-u4-X08"},{"t":"△ + 9 = □","mis":"M5-1-u4-X02"}],"explanation":["□ × 9 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ ÷ 9 = □ — 셈이 거꾸로 바뀌어요.","□ = 3이면 3 × 9 = 27, 거꾸로 27 ÷ 9 = 3으로 같은 짝이에요."]}]}}'::jsonb),
('g5_1_math_u4_L03_basic#5','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C4',2,'mc','auto','원호는 동생보다 3살 많아요. 원호 나이를 □, 동생 나이를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X04','M5-1-u4-X02']::text[],true,'{"seq":5,"concept":"M5-1-u4-C4","difficulty":2,"kind":"mc","stem":"원호는 동생보다 3살 많아요. 원호 나이를 □, 동생 나이를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ − 3 = △","correct":true},{"t":"□ + 3 = △","mis":"M5-1-u4-X04"},{"t":"□ × 3 = △","mis":"M5-1-u4-X02"},{"t":"△ − 3 = □","mis":"M5-1-u4-X04"}],"explanation":["말로 먼저 해요 — △(동생 나이)는 □(원호 나이)보다 3 적어요.","그 말을 그대로 옮기면 □ − 3 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."],"variant_rule":{"alt":[{"stem":"언니는 나보다 4살 많아요. 언니 나이를 □, 내 나이를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ − 4 = △","correct":true},{"t":"□ + 4 = △","mis":"M5-1-u4-X04"},{"t":"□ × 4 = △","mis":"M5-1-u4-X02"},{"t":"△ − 4 = □","mis":"M5-1-u4-X04"}],"explanation":["말로 먼저 해요 — △(내 나이)는 □(언니 나이)보다 4 적어요.","그 말을 그대로 옮기면 □ − 4 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]},{"stem":"형은 나보다 2살 많아요. 내 나이를 □, 형 나이를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ + 2 = △","correct":true},{"t":"□ × 2 = △","mis":"M5-1-u4-X02"},{"t":"△ + 2 = □","mis":"M5-1-u4-X04"},{"t":"□ − 2 = △","mis":"M5-1-u4-X04"}],"explanation":["말로 먼저 해요 — △(형 나이)는 □(내 나이)보다 2 많아요.","그 말을 그대로 옮기면 □ + 2 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]}]}}'::jsonb),
('g5_1_math_u4_L03_basic#6','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C4',2,'mc','auto','자동차 수를 □, 바퀴 수를 △라고 할 때 표를 보고 쓴 식 중 잘못된 것은 어느 것인가요?',ARRAY['M5-1-u4-X13']::text[],true,'{"seq":6,"concept":"M5-1-u4-C4","difficulty":2,"kind":"mc","stem":"자동차 수를 □, 바퀴 수를 △라고 할 때 표를 보고 쓴 식 중 잘못된 것은 어느 것인가요?","options":[{"t":"□ + 3 = △","correct":true},{"t":"□ × 4 = △","mis":"M5-1-u4-X13"},{"t":"△ ÷ 4 = □","mis":"M5-1-u4-X13"},{"t":"△ = □ × 4","mis":"M5-1-u4-X13"}],"explanation":["위아래 짝 1과 4, 2와 8, 3과 12를 모두 보면 △는 □의 4배예요.","□ + 3 = △는 첫 짝에서만 맞아요 — 둘째 짝 2 + 3 = 5이지만 실제 △는 8이에요.","나머지 셋은 같은 관계를 다르게 쓴 맞는 식이에요."],"asset":{"type":"numgrid","rows":[["자동차 수",1,2,3,4,5],["바퀴 수",4,8,12,16,20]],"name":"대응표"},"variant_rule":{"alt":[{"stem":"피자 수를 □, 조각 수를 △라고 할 때 표를 보고 쓴 식 중 잘못된 것은 어느 것인가요?","options":[{"t":"□ + 7 = △","correct":true},{"t":"□ × 8 = △","mis":"M5-1-u4-X13"},{"t":"△ ÷ 8 = □","mis":"M5-1-u4-X13"},{"t":"△ = □ × 8","mis":"M5-1-u4-X13"}],"explanation":["위아래 짝 1과 8, 2와 16, 3과 24를 모두 보면 △는 □의 8배예요.","□ + 7 = △는 첫 짝에서만 맞아요 — 둘째 짝 2 + 7 = 9이지만 실제 △는 16이에요.","나머지 셋은 같은 관계를 다르게 쓴 맞는 식이에요."],"asset":{"type":"numgrid","rows":[["피자 수",1,2,3,4,5],["조각 수",8,16,24,32,40]],"name":"대응표"}},{"stem":"삼각형 수를 □, 변의 수를 △라고 할 때 표를 보고 쓴 식 중 잘못된 것은 어느 것인가요?","options":[{"t":"□ + 2 = △","correct":true},{"t":"□ × 3 = △","mis":"M5-1-u4-X13"},{"t":"△ ÷ 3 = □","mis":"M5-1-u4-X13"},{"t":"△ = □ × 3","mis":"M5-1-u4-X13"}],"explanation":["위아래 짝 1과 3, 2와 6, 3과 9를 모두 보면 △는 □의 3배예요.","□ + 2 = △는 첫 짝에서만 맞아요 — 둘째 짝 2 + 2 = 4이지만 실제 △는 6이에요.","나머지 셋은 같은 관계를 다르게 쓴 맞는 식이에요."],"asset":{"type":"numgrid","rows":[["삼각형 수",1,2,3,4,5],["변의 수",3,6,9,12,15]],"name":"대응표"}}]}}'::jsonb),
